// Generated by scripts/embed-jirau.ts from jirau/. Do not edit; run `bun scripts/embed-jirau.ts`.
export const JIRAU_FILES: Record<string, string> = {
  ".claude-plugin/plugin.json": "{\n  \"name\": \"pororoca-jirau\",\n  \"version\": \"0.1.0\",\n  \"description\": \"Jirau, the Pororoca cockpit: what needs you and what the fleet is doing, beside the chat\",\n  \"types\": \"./types/index.d.ts\",\n  \"author\": {\n    \"name\": \"Roberto Campos\",\n    \"url\": \"https://github.com/cavalcanticampos\"\n  },\n  \"homepage\": \"https://cavalcanticampos.github.io/pororoca/jirau.html\",\n  \"license\": \"MIT\"\n}\n",
  "hooks/hooks.json": "{ \"modules\": [\"./register.tsx\"] }\n",
  "hooks/model.ts": "// Pure logic of the Jirau pane: parsing what `pororoca jirau snapshot --json` prints and\n// what the person types after `/jirau`. No engine calls here, so it is tested with plain bun.\n\nexport type LaneCard = {\n  id: number\n  title: string\n  reason: string\n  draft: string\n  pr: string\n  escalated: boolean\n}\n\nexport type ActiveCard = {\n  id: number\n  title: string\n  /** The real state, in words: \"investigating\", \"waiting on ana\", \"building\"... never \"delivered\" while open. */\n  label: string\n  stalled: boolean\n  since: string\n}\n\nexport type Snapshot = {\n  fleet: string\n  running: boolean\n  pausedUntil: string\n  repair: number\n  lane: LaneCard[]\n  active: ActiveCard[]\n  resolvedWithoutYou: number | null\n  corrections: number\n  at: string\n}\n\nconst str = (v: unknown) => (typeof v === 'string' ? v : '')\nconst num = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : 0)\n\n/** Reads the CLI's JSON defensively: an older or newer CLI must not break the pane. */\nexport function parseSnapshot(text: string): Snapshot {\n  const o = JSON.parse(text) as Record<string, unknown>\n  const lane = Array.isArray(o.lane) ? (o.lane as Record<string, unknown>[]) : []\n  const active = Array.isArray(o.active) ? (o.active as Record<string, unknown>[]) : []\n  const m = (o.metrics ?? {}) as Record<string, unknown>\n  return {\n    fleet: str(o.fleet) || 'fleet',\n    running: o.running === true,\n    pausedUntil: str(o.pausedUntil),\n    repair: num(o.repair),\n    lane: lane.map(c => ({\n      id: num(c.id),\n      title: str(c.title),\n      reason: str(c.reason),\n      draft: str(c.draft),\n      pr: str(c.pr),\n      escalated: c.escalated === true,\n    })),\n    active: active.map(c => ({\n      id: num(c.id),\n      title: str(c.title),\n      label: str(c.label) || str(c.state),\n      stalled: c.stalled === true,\n      since: str(c.since),\n    })),\n    resolvedWithoutYou: typeof m.resolvedWithoutYou === 'number' ? m.resolvedWithoutYou : null,\n    corrections: num(m.corrections),\n    at: str(o.at),\n  }\n}\n\nexport const VERBS = ['send', 'edit', 'decide', 'ignore', 'later', 'merge'] as const\nexport type Verb = (typeof VERBS)[number]\nconst NEEDS_TEXT: Verb[] = ['edit', 'decide']\n\nexport type Command =\n  | { kind: 'open' }\n  | { kind: 'refresh' }\n  | { kind: 'help' }\n  | { kind: 'act'; verb: Verb; id: number; text: string }\n  | { kind: 'error'; message: string }\n\nexport const HELP =\n  '/jirau opens the pane · /jirau send N · /jirau edit N <text> · /jirau decide N <text> · /jirau ignore N · /jirau later N · /jirau merge N · /jirau refresh'\n\n/** `/jirau send 3`, `/jirau edit 3 new text`, `/jirau #3 send` is not accepted: verb first. */\nexport function parseCommand(args: string): Command {\n  const words = args.trim().split(/\\s+/).filter(Boolean)\n  if (words.length === 0) return { kind: 'open' }\n  const [first, second, ...rest] = words\n  const verb = first!.toLowerCase()\n  if (verb === 'refresh' || verb === 'r') return { kind: 'refresh' }\n  if (verb === 'help') return { kind: 'help' }\n  if (!(VERBS as readonly string[]).includes(verb)) return { kind: 'error', message: `unknown action \"${first}\". ${HELP}` }\n  const id = Number(String(second ?? '').replace(/^#/, ''))\n  if (!Number.isInteger(id) || id <= 0) return { kind: 'error', message: `which card? e.g. /jirau ${verb} 3` }\n  const text = rest.join(' ')\n  if (NEEDS_TEXT.includes(verb as Verb) && !text) return { kind: 'error', message: `/jirau ${verb} ${id} needs the text` }\n  return { kind: 'act', verb: verb as Verb, id, text }\n}\n\n/** The CLI argv for an action. */\nexport function actionArgv(bin: string, c: { verb: Verb; id: number; text: string }): string[] {\n  return c.text ? [bin, c.verb, String(c.id), c.text] : [bin, c.verb, String(c.id)]\n}\n\nexport function cut(t: string, n: number): string {\n  const one = t.replace(/\\s+/g, ' ').trim()\n  return one.length > n ? one.slice(0, Math.max(1, n - 1)) + '…' : one\n}\n\n/** \"5m\", \"3h\", \"2d\" since an ISO time. */\nexport function ago(iso: string, now: Date): string {\n  const t = Date.parse(iso)\n  if (Number.isNaN(t)) return ''\n  const m = Math.max(0, Math.round((now.getTime() - t) / 60000))\n  if (m < 60) return `${m}m`\n  if (m < 48 * 60) return `${Math.round(m / 60)}h`\n  return `${Math.round(m / 1440)}d`\n}\n\nexport function headline(s: Snapshot): string {\n  const parts = [s.running ? 'running' : 'stopped']\n  if (s.pausedUntil) parts.push(`paused until ${s.pausedUntil.slice(11, 16)} (usage limit)`)\n  if (s.repair) parts.push(`${s.repair} in repair`)\n  return parts.join(' · ')\n}\n\n/** Recognises the CLI's \"no maloca.yaml\" error, so the pane can say `pororoca init` instead of a stack of text. */\nexport function isNoFleet(stderr: string): boolean {\n  return /no .*maloca\\.yaml|pororoca init/i.test(stderr)\n}\n",
  "hooks/register.tsx": "// Jirau: the Pororoca cockpit, a pane beside the chat.\n// It reads `pororoca jirau snapshot --json` every 10 s and acts on cards through the same CLI.\n\nimport { atom, read, update } from 'claude-code'\nimport type { EngineInterface, Register } from 'claude-code'\n\nimport { actionArgv, ago, cut, headline, HELP, isNoFleet, parseCommand, parseSnapshot, type Verb } from './model'\n\nconst PANE = 'pororoca-jirau'\nconst TITLE = 'jirau'\nconst EVERY_MS = 10_000\n\nconst snap = atom({ plugin: 'pororoca-jirau', key: 'snap' } as const, null, { shape: 'snap-1' })\nconst erro = atom({ plugin: 'pororoca-jirau', key: 'erro' } as const, '')\nconst quando = atom({ plugin: 'pororoca-jirau', key: 'quando' } as const, '')\nconst aberto = atom({ plugin: 'pororoca-jirau', key: 'aberto' } as const, null)\nconst busy = atom({ plugin: 'pororoca-jirau', key: 'busy' } as const, false)\nconst semFrota = atom({ plugin: 'pororoca-jirau', key: 'semFrota' } as const, false)\n\n// Where the fleet lives and which binary to call. Set in session.start; a reload runs it again.\nlet bin = 'pororoca'\nlet dir = ''\n\nasync function locate($: EngineInterface) {\n  bin = (await $.env.get('POROROCA_BIN')) || 'pororoca'\n  dir = (await $.env.get('POROROCA_DIR')) || (await $.session.root())\n}\n\n/** Reads the fleet. Resolves whether a fleet was found. */\nasync function refresh($: EngineInterface): Promise<boolean> {\n  if (await read($, busy)) return !(await read($, semFrota))\n  await update($, busy, () => true)\n  try {\n    const r = await $.process.run([bin, 'jirau', 'snapshot', '--json'], { cwd: dir, timeoutMs: 20_000 })\n    if (r.exitCode !== 0) {\n      if (isNoFleet(r.stderr)) {\n        await update($, semFrota, () => true)\n        await update($, erro, () => '')\n        return false\n      }\n      throw new Error((r.stderr || r.stdout || `exit ${r.exitCode}`).trim().split('\\n').pop())\n    }\n    const s = parseSnapshot(r.stdout)\n    const before = new Set(((await read($, snap))?.lane ?? []).map(c => c.id))\n    const arrived = s.lane.filter(c => !before.has(c.id))\n    const hadBefore = (await read($, snap)) !== null\n    await update($, snap, () => s)\n    await update($, semFrota, () => false)\n    await update($, erro, () => '')\n    const d = new Date()\n    await update($, quando, () => `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}:${String(d.getSeconds()).padStart(2, '0')}`)\n    if (hadBefore && arrived.length > 0) $.ui.toast(`jirau: needs you, #${arrived[0]!.id} ${cut(arrived[0]!.title, 60)}`)\n    return true\n  } catch (err) {\n    const msg = String((err as Error)?.message ?? err)\n    await update($, erro, () =>\n      /ENOENT|not found|cannot start/i.test(msg) ? `can't run \"${bin}\". Install Pororoca or set POROROCA_BIN.` : cut(msg, 200),\n    )\n    return true\n  } finally {\n    await update($, busy, () => false)\n  }\n}\n\nasync function act($: EngineInterface, verb: Verb, id: number, text = ''): Promise<string> {\n  const r = await $.process.run(actionArgv(bin, { verb, id, text }), { cwd: dir, timeoutMs: 120_000 })\n  await refresh($)\n  const out = (r.exitCode === 0 ? r.stdout : r.stderr || r.stdout).trim()\n  if (r.exitCode !== 0) $.ui.toast(`jirau: ${cut(out, 80)}`)\n  return out || `${verb} #${id}`\n}\n\nexport const register: Register = on => {\n  on('session.start', async ($, e, next) => {\n    await locate($)\n    await $.command.register({ name: 'jirau', description: 'Pororoca cockpit: what needs you and what the fleet is doing' })\n    // Opens by itself only where a fleet lives, so the mod stays quiet in every other session.\n    if (await refresh($)) {\n      void $.ui.open({ id: PANE, title: TITLE })\n      $.clock.every(EVERY_MS, () => refresh($))\n    }\n    return next(e)\n  })\n\n  on('command.run', { command: 'jirau' }, async ($, e) => {\n    if (!dir) await locate($)\n    const c = parseCommand(e.args)\n    if (c.kind === 'error') return { text: c.message }\n    if (c.kind === 'help') return { text: HELP }\n    if (c.kind === 'act') return { text: await act($, c.verb, c.id, c.text) }\n    const found = await refresh($)\n    if (!found)\n      return { text: `No Pororoca fleet in ${dir}. Run \\`pororoca init\\` there, or set POROROCA_DIR to the folder that holds maloca.yaml.` }\n    if (c.kind === 'open') {\n      await $.ui.open({ id: PANE, title: TITLE })\n      return { text: 'Jirau open.' }\n    }\n    return { text: 'Refreshed.' }\n  })\n\n  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {\n    const { Box, Text, Button } = $.ui.resolve(e)\n    const s = await read($, snap)\n    const falha = await read($, erro)\n    const hora = await read($, quando)\n    const ocupado = await read($, busy)\n    const sel = await read($, aberto)\n    const vazio = await read($, semFrota)\n    // the pane's own body width, not the terminal's\n    const larg = Math.max(24, (e.props?.bodyColumns ?? e.viewport?.columns ?? 50) - 3)\n    const now = new Date()\n\n    if (vazio || !s) {\n      return (\n        <Box flexDirection=\"column\" paddingX={1}>\n          <Text color=\"claude\" bold>🛖 jirau</Text>\n          {falha !== '' ? <Text color=\"error\">⚠ {cut(falha, larg)}</Text> : null}\n          <Text dimColor>{vazio ? `No Pororoca fleet in ${cut(dir, larg - 22)}.` : 'Reading the fleet…'}</Text>\n          {vazio ? <Text dimColor>Run `pororoca init` there, or set POROROCA_DIR.</Text> : null}\n        </Box>\n      )\n    }\n\n    const n = s.lane.length\n    const pct = s.resolvedWithoutYou === null ? '' : `${Math.round(s.resolvedWithoutYou * 100)}% without you`\n    return (\n      <Box flexDirection=\"column\" paddingX={1}>\n        <Box flexDirection=\"row\" justifyContent=\"space-between\">\n          <Box flexDirection=\"row\" gap={1}>\n            <Text color=\"claude\" bold>🛖 {cut(s.fleet, 20)}</Text>\n            <Text color={s.pausedUntil || s.repair ? 'warning' : s.running ? 'success' : 'subtle'}>{headline(s)}</Text>\n          </Box>\n          <Button key=\"refresh\" plain hotkey=\"r\" onPress={() => void refresh($)}>\n            <Text dimColor>{ocupado ? '↻ …' : `↻ ${hora || '--:--'}`}</Text>\n          </Button>\n        </Box>\n        <Text color=\"subtle\">{'─'.repeat(larg)}</Text>\n        {falha !== '' ? <Text color=\"error\">⚠ {cut(falha, larg)}</Text> : null}\n\n        <Text color={n === 0 ? 'success' : 'error'} bold>{n === 0 ? '✋ nothing needs you' : `✋ ${n} need${n === 1 ? 's' : ''} you`}</Text>\n        {s.lane.map(c => {\n          const open = sel === c.id\n          return (\n            <Box key={`lane-${c.id}`} flexDirection=\"column\" marginTop={1}>\n              <Button key={`toggle-${c.id}`} plain onPress={() => void update($, aberto, a => (a === c.id ? null : c.id))}>\n                <Text color={c.escalated ? 'warning' : 'error'}>{open ? '▾' : '●'}</Text>\n                <Text bold={open}> #{c.id} {cut(c.title, larg - 8)}</Text>\n              </Button>\n              <Box paddingLeft={2}>\n                <Text dimColor>{cut(c.escalated ? `chased without progress · ${c.reason}` : c.reason, larg - 2)}</Text>\n              </Box>\n              {open ? (\n                <Box flexDirection=\"column\" borderStyle=\"round\" borderColor=\"claude\" paddingX={1} marginLeft={2}>\n                  {c.draft !== '' ? (\n                    <Box flexDirection=\"column\">\n                      <Text color=\"claude\" bold>Draft</Text>\n                      <Text>{cut(c.draft, 600)}</Text>\n                    </Box>\n                  ) : null}\n                  {c.pr !== '' ? <Text color=\"suggestion\" underline>{c.pr}</Text> : null}\n                  <Box flexDirection=\"row\" gap={2} marginTop={1}>\n                    {c.draft !== '' ? (\n                      <Button key={`send-${c.id}`} onPress={() => void act($, 'send', c.id)}>\n                        <Text color=\"success\">send</Text>\n                      </Button>\n                    ) : null}\n                    {c.pr !== '' ? (\n                      <Button key={`merge-${c.id}`} onPress={() => void act($, 'merge', c.id)}>\n                        <Text color=\"success\">merge</Text>\n                      </Button>\n                    ) : null}\n                    <Button key={`later-${c.id}`} onPress={() => void act($, 'later', c.id)}>\n                      <Text>later</Text>\n                    </Button>\n                    <Button key={`ignore-${c.id}`} onPress={() => void act($, 'ignore', c.id)}>\n                      <Text dimColor>ignore</Text>\n                    </Button>\n                  </Box>\n                  <Text dimColor>/jirau edit {c.id} &lt;your text&gt; · /jirau decide {c.id} &lt;what to do&gt;</Text>\n                </Box>\n              ) : null}\n            </Box>\n          )\n        })}\n\n        <Box marginTop={1}>\n          <Text color=\"subtle\">{'─'.repeat(larg)}</Text>\n        </Box>\n        <Text color=\"claude\" bold>🌊 the fleet is on {s.active.length}</Text>\n        {s.active.length === 0 ? <Text dimColor>Nothing in flight.</Text> : null}\n        {s.active.map(c => (\n          <Box key={`act-${c.id}`} flexDirection=\"row\" gap={1}>\n            <Text color={c.stalled ? 'warning' : 'subtle'}>{c.stalled ? '⚠' : '·'}</Text>\n            <Text dimColor>#{c.id}</Text>\n            <Text color={c.stalled ? 'warning' : 'text'}>{cut(c.label, 22)}</Text>\n            <Text dimColor>{cut(`${c.title}${c.since ? ` · ${ago(c.since, now)}` : ''}`, Math.max(10, larg - 30))}</Text>\n          </Box>\n        ))}\n\n        <Box marginTop={1}>\n          <Text dimColor italic>{[pct, s.corrections ? `${s.corrections} corrections this week` : '', 'r refreshes'].filter(Boolean).join(' · ')}</Text>\n        </Box>\n      </Box>\n    )\n  })\n}\n",
  "tsconfig.json": "{ \"extends\": \"./.claude-plugin/types/tsconfig.json\" }\n",
  "types/index.d.ts": "// The values the Jirau pane keeps in $.state. Same shapes as hooks/model.ts, which the\n// pane's pure logic (and its bun tests) use; the contract must not import, so they are spelled here.\n\ndeclare module 'claude-code' {\n  interface PluginState {\n    'pororoca-jirau': {\n      snap: Shaped<{\n        fleet: string\n        running: boolean\n        pausedUntil: string\n        repair: number\n        lane: { id: number; title: string; reason: string; draft: string; pr: string; escalated: boolean }[]\n        active: { id: number; title: string; label: string; stalled: boolean; since: string }[]\n        resolvedWithoutYou: number | null\n        corrections: number\n        at: string\n      } | null>\n      erro: string\n      quando: string\n      aberto: number | null\n      busy: boolean\n      semFrota: boolean\n    }\n  }\n}\n"
};
